import { Feat, FeatMechanics } from "@/interfaces/Feat";
import { Edition } from "@/interfaces/Edition";
import FEAT_MECHANICS_JSON from "./featMechanics.json";

/**
 * Structured feat effects (data/featMechanics.json, generated by
 * scripts/feats/build_feat_mechanics.py from 5e.tools' feat data), keyed by
 * edition then by the feat's exact name in data/<edition>/feats/Feats.ts.
 * Cast once here so TypeScript doesn't have to infer a type for the whole
 * 230KB JSON literal everywhere it's used.
 */
const FEAT_MECHANICS = FEAT_MECHANICS_JSON as unknown as Record<Edition, Record<string, FeatMechanics>>;

/** Returns `feats` with each one's `mechanics` filled in from featMechanics.json (feats with no entry are returned unchanged). */
export function withFeatMechanics(feats: Feat[], edition: Edition): Feat[] {
  const table = FEAT_MECHANICS[edition] ?? {};
  return feats.map((feat) => (table[feat.name] ? { ...feat, mechanics: table[feat.name] } : feat));
}
